public class DatasetUtilities_iterateRangeBounds_TriageGen0Test {

    @Test
    public void testStandardXYDataset_NormalValues() {
        XYDataset dataset = mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(2);
        when(dataset.getItemCount(0)).thenReturn(2);
        when(dataset.getItemCount(1)).thenReturn(1);

        when(dataset.getYValue(0, 0)).thenReturn(10.0);
        when(dataset.getYValue(0, 1)).thenReturn(5.0);
        when(dataset.getYValue(1, 0)).thenReturn(20.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);
        assertNotNull(result);
        assertEquals(5.0, result.getLower(), 1e-9);
        assertEquals(20.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testStandardXYDataset_WithNaN() {
        XYDataset dataset = mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);

        when(dataset.getYValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getYValue(0, 1)).thenReturn(15.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);
        assertNotNull(result);
        assertEquals(15.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testStandardXYDataset_EmptyOrAllNaN() {
        XYDataset dataset = mock(XYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);
        assertNull(result);
    }

    @Test
    public void testIntervalXYDataset_IncludeInterval_Normal() {
        // Note: The code has a specific logic: for (int series = 1; series < seriesCount; series++)
        // It skips series index 0 for IntervalXYDataset when includeInterval is true.
        IntervalXYDataset dataset = mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(3); // series 0, 1, 2

        // Series 1
        when(dataset.getItemCount(1)).thenReturn(1);
        when(dataset.getYValue(1, 0)).thenReturn(10.0);
        when(dataset.getStartYValue(1, 0)).thenReturn(5.0);
        when(dataset.getEndYValue(1, 0)).thenReturn(15.0);

        // Series 2
        when(dataset.getItemCount(2)).thenReturn(1);
        when(dataset.getYValue(2, 0)).thenReturn(Double.NaN);
        when(dataset.getStartYValue(2, 0)).thenReturn(2.0);
        when(dataset.getEndYValue(2, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);
        assertNotNull(result);
        assertEquals(2.0, result.getLower(), 1e-9);
        assertEquals(15.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIntervalXYDataset_IncludeInterval_WithNaN() {
        IntervalXYDataset dataset = mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(2);
        when(dataset.getItemCount(1)).thenReturn(1);

        when(dataset.getYValue(1, 0)).thenReturn(Double.NaN);
        when(dataset.getStartYValue(1, 0)).thenReturn(Double.NaN);
        when(dataset.getEndYValue(1, 0)).thenReturn(100.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);
        assertNotNull(result);
        assertEquals(100.0, result.getLower(), 1e-9);
        assertEquals(100.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testOHLCDataset_IncludeInterval() {
        OHLCDataset dataset = mock(OHLCDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(2);

        // Item 0
        when(dataset.getLowValue(0, 0)).thenReturn(10.0);
        when(dataset.getHighValue(0, 0)).thenReturn(20.0);

        // Item 1
        when(dataset.getLowValue(0, 1)).thenReturn(Double.NaN);
        when(dataset.getHighValue(0, 1)).thenReturn(30.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);
        assertNotNull(result);
        assertEquals(10.0, result.getLower(), 1e-9);
        assertEquals(30.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testOHLCDataset_IncludeInterval_AllNaN() {
        OHLCDataset dataset = mock(OHLCDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getLowValue(0, 0)).thenReturn(Double.NaN);
        when(dataset.getHighValue(0, 0)).thenReturn(Double.NaN);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, true);
        assertNull(result);
    }

    @Test
    public void testIncludeInterval_False_TriggersStandardCase() {
        // Even if it is an IntervalXYDataset, if includeInterval is false, it should use standard logic (series 0 included)
        IntervalXYDataset dataset = mock(IntervalXYDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(50.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);
        assertNotNull(result);
        assertEquals(50.0, result.getLower(), 1e-9);
        assertEquals(50.0, result.getUpper(), 1e-9);
    }

    @Test
    public void testIncludeInterval_False_TriggersStandardCase_OHLC() {
        // Even if it is an OHLCDataset, if includeInterval is false, it should use standard logic
        OHLCDataset dataset = mock(OHLCDataset.class);
        when(dataset.getSeriesCount()).thenReturn(1);
        when(dataset.getItemCount(0)).thenReturn(1);
        when(dataset.getYValue(0, 0)).thenReturn(25.0);

        Range result = DatasetUtilities.iterateRangeBounds(dataset, false);
        assertNotNull(result);
        assertEquals(25.0, result.getLower(), 1e-9);
        assertEquals(25.0, result.getUpper(), 1e-9);
    }
